begin;
do $$
declare cfg jsonb;r jsonb;rid bigint;rid2 bigint;e1 bigint;e2 bigint;batch jsonb;delivery uuid;lease uuid;v jsonb;runtime jsonb;acct uuid:=gen_random_uuid();
begin
 delete from public.s2a_ops_mail_queue;delete from public.s2a_ops_mail_delivery;delete from public.s2a_ops_mail_attempts;
 update public.s2a_settings set data=data||'{"ops_monitoring_enabled":true}' where id='11111111-0000-4000-8000-000000000001';
 cfg:=public.s2a_ops_email_set('{"alert":{"enabled":true,"recipients":["fixture@example.com"],"batching_window_seconds":60,"rate_limit_per_hour":1,"include_resolved_alerts":true}}');
 assert cfg->'report'->>'daily_summary_schedule'='0 9 * * *';
 assert cfg->'alert'->>'min_severity'='' and cfg->'alert'->>'rate_limit_per_hour'='1','partial blocks retain defaults';
 r:=public.s2a_ops_alert_rule_save(null,'{"name":"Mail fixture","metric_type":"concurrency_queue_depth","operator":">=","threshold":0,"severity":"P0"}');rid:=(r->>'id')::bigint;
 insert into public.s2a_ops_alert_events(rule_id,severity,title) values(rid,'P0','Fixture 1') returning id into e1;
 r:=public.s2a_ops_alert_rule_save(null,'{"name":"Mail fixture 2","metric_type":"concurrency_queue_depth","operator":">=","threshold":0,"severity":"P0"}');rid2:=(r->>'id')::bigint;
 insert into public.s2a_ops_alert_events(rule_id,severity,title) values(rid2,'P0','Fixture 2') returning id into e2;
 assert (select count(*) from public.s2a_ops_mail_queue where event_id in(e1,e2))=2;
 assert public.s2a_ops_mail_claim()='[]'::jsonb,'batch window delays sending';
 update public.s2a_ops_mail_queue set ready_at=now()-interval '1 second' where event_id=e1;
 batch:=public.s2a_ops_mail_claim();assert jsonb_array_length(batch)=1;
 assert jsonb_array_length(batch->0->'payload')=2,'a delivery batches one recipient across the window';
 delivery:=(batch->0->>'id')::uuid;lease:=(batch->0->>'lease_id')::uuid;
 assert public.s2a_ops_mail_claim()='[]'::jsonb,'leased messages cannot be claimed twice';
 assert not public.s2a_ops_mail_finish(delivery,gen_random_uuid(),null);
 assert public.s2a_ops_mail_finish(delivery,lease,'delivery_failed');
 assert not (select email_sent from public.s2a_ops_alert_events where id=e1),'failure cannot mark delivery';
 update public.s2a_ops_mail_delivery set ready_at=now()-interval '1 second' where id=delivery;
 assert public.s2a_ops_mail_claim()='[]'::jsonb,'attempt reservations enforce hourly limits across retries';
 delete from public.s2a_ops_mail_attempts;
 batch:=public.s2a_ops_mail_claim();assert (batch->0->>'id')::uuid=delivery,'retry keeps idempotency key';
 assert public.s2a_ops_mail_finish(delivery,(batch->0->>'lease_id')::uuid,null);
 assert (select bool_and(email_sent) from public.s2a_ops_alert_events where id in(e1,e2));
 assert not public.s2a_ops_mail_finish(delivery,(batch->0->>'lease_id')::uuid,null),'completion is idempotent';
 runtime:=public.s2a_ops_alert_runtime_get();
 perform public.s2a_ops_alert_runtime_set(jsonb_set(jsonb_set(runtime,'{silencing,enabled}','true'),'{silencing,global_until_rfc3339}',to_jsonb(to_char((now()+interval '1 hour') at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS"Z"'))));
 assert not public.s2a_ops_mail_alert_allowed(e1,'firing');
 perform public.s2a_ops_alert_runtime_set(runtime);
 perform public.s2a_ops_email_set('{"alert":{"min_severity":"critical"}}');
 insert into public.s2a_ops_alert_events(rule_id,severity,title,status) values(rid,'P2','Low severity','resolved');
 assert (select count(*) from public.s2a_ops_mail_queue)=2,'low severity does not enqueue';
 perform public.s2a_ops_email_set('{"alert":{"batching_window_seconds":0,"rate_limit_per_hour":0}}');
 perform public.s2a_ops_alert_event_status(e1,'manual_resolved');
 assert (select count(*) from public.s2a_ops_mail_queue where event_id=e1)=2,'resolved alerts use an independent transition';
 batch:=public.s2a_ops_mail_claim();delivery:=(batch->0->>'id')::uuid;
 update public.s2a_ops_mail_delivery set first_attempt_at=now()-interval '24 hours',lease_until=now()-interval '1 second' where id=delivery;
 assert public.s2a_ops_mail_claim()='[]'::jsonb;
 assert (select status from public.s2a_ops_mail_delivery where id=delivery)='failed','expired idempotency windows never resend';
 -- Exercise reports without requiring Cron in the standalone PostgreSQL harness.
 update public.s2a_settings set data=jsonb_set(data,'{ops_email_config,report}',(cfg->'report')||'{"enabled":true,"recipients":["report@example.com"],"daily_summary_enabled":true,"weekly_summary_enabled":true,"error_digest_enabled":true,"account_health_enabled":true,"account_health_error_rate_threshold":0,"error_digest_min_count":0}') where id='11111111-0000-4000-8000-000000000001';
 assert public.s2a_ops_mail_report_enqueue('daily_summary')->'queued'='true'::jsonb;
 perform public.s2a_ops_mail_report_enqueue('daily_summary');
 assert (select count(*) from public.s2a_ops_mail_queue where report_type='daily_summary')=1,'report minute deduplication';
 assert public.s2a_ops_mail_report_enqueue('weekly_summary')->'queued'='true'::jsonb;
 assert public.s2a_ops_mail_report_enqueue('error_digest')->'queued'='true'::jsonb;
 insert into public.s2a_accounts(id,name,account_fingerprint,ciphertext,iv,type) values(acct,'Mail health fixture',acct::text,'fixture','fixture','apikey');
 perform public.s2a_ops_error_record(jsonb_build_object('event_id',gen_random_uuid(),'request_id',gen_random_uuid(),'kind','request','phase','upstream','type','provider_error','owner','provider','source','upstream_http','code','provider_error','limited',false,'status_code',502,'account_id',acct,'platform','openai'));
 assert public.s2a_ops_mail_report_enqueue('account_health')->'queued'='true'::jsonb;
 assert exists(select 1 from public.s2a_ops_mail_queue mq cross join lateral jsonb_array_elements(mq.payload->'accounts_above_threshold') row where mq.report_type='account_health' and row->>'account_id'=acct::text and row->>'error_rate'='100.00'),'health threshold evaluates actual per-account requests';
 batch:=public.s2a_ops_mail_claim();assert jsonb_array_length(batch)=1 and jsonb_array_length(batch->0->'payload')=4,'report delivery batches the due summaries';
 if exists(select 1 from pg_catalog.pg_extension where extname='pg_cron') then
  perform public.s2a_ops_email_scheduler_configure();
  execute 'select count(*) from cron.job where jobname in(''s2a-ops-daily_summary'',''s2a-ops-weekly_summary'',''s2a-ops-error_digest'',''s2a-ops-account_health'')' into rid;assert rid=4;
  perform public.s2a_ops_email_set('{"report":{"enabled":false}}');
  execute 'select count(*) from cron.job where jobname in(''s2a-ops-daily_summary'',''s2a-ops-weekly_summary'',''s2a-ops-error_digest'',''s2a-ops-account_health'')' into rid;assert rid=0;
 end if;
 assert not has_table_privilege('service_role','public.s2a_ops_mail_queue','SELECT');
 assert not has_function_privilege('authenticated','public.s2a_ops_mail_claim(text)','EXECUTE');
 begin perform public.s2a_ops_email_set('{"alert":{"rate_limit_per_hour":0.5}}');raise exception 'fractional limit accepted';exception when raise_exception then assert sqlerrm='invalid_email_config';end;
end $$;
rollback;
